  ('5b36c547-90f6-5f36-9c88-e44daf12fd72'::uuid, TIMESTAMPTZ '2026-10-06 00:00:00+00', TIMESTAMPTZ '2026-10-06 00:00:00+00', FALSE, E'HIGHLIGHT_INCORRECT_WORDS', E'HIGHLIGHT_INCORRECT_WORDS', E'LISTENING', 'SHARED', NULL, 'APPROVED', '5b36c547-90f6-5f36-9c88-e44daf12fd72'::uuid, 1, NULL, TRUE, 0, NULL, E'DEMO22 - HIGHLIGHT_INCORRECT_WORDS - 1', E'Climate scientists warn that local temperatures will continue to rise unless countries increase their carbon emissions. Many governments have refused to invest in renewable energy, but progress has been faster than expected, and experts say minor action is still needed.', 'df61cbab-8454-5606-aa0d-9d6b23b5eaf8'::uuid, NULL, NULL, E'[4,12,19,29,35]', NULL, NULL),
