  ('50c34612-aaf6-5625-a5ab-5299478016c6'::uuid, '779086a4-e716-5a9a-a3db-8981e4872cf7'::uuid, TIMESTAMPTZ '2026-10-06 00:00:00+00', TIMESTAMPTZ '2026-10-06 00:00:00+00', FALSE, E'After World War II, especially in North America, there was a boom in general aviation, both private and commercial, as thousands of pilots were released from military service and much inexpensive war-surplus transport and training aircraft became available.', FALSE, 0, NULL, NULL),
  ('c3798223-f21d-547b-9834-ae6ae40979af'::uuid, '779086a4-e716-5a9a-a3db-8981e4872cf7'::uuid, TIMESTAMPTZ '2026-10-06 00:00:00+00', TIMESTAMPTZ '2026-10-06 00:00:00+00', FALSE, E'By the 1950s, the development of civil jets grew, beginning with the de Havilland Comet, though the first widely used passenger jet was the Boeing 707 because it was much more economical than other aircraft at that time.', FALSE, 2, NULL, NULL),
